import Foundation
import Testing

@testable import CloudSync

/// The record itself, and the two places where it could silently break.
@Suite("The CloudRecord")
struct CloudRecordTests {

    /// **A mirror from before the field was added must stay readable.**
    ///
    /// ``CloudRecord/encrypted`` was added later. The decoding generated by Swift
    /// demands every key; on devices running an earlier build the whole mirror would
    /// have become unreadable, and with it the queue: everything written without
    /// network and not yet sent.
    @Test("An old mirror without the field stays readable")
    func oldSnapshot() throws {
        let legacyJSON = """
            {"typ":"Profileinstellung","name":"theme","geaendert":780000000,
             "felder":{"wert":{"text":{"_0":"indigo"}}}}
            """
        let makeRecord = try JSONDecoder().decode(CloudRecord.self, from: Data(legacyJSON.utf8))
        #expect(makeRecord.name == "theme")
        #expect(makeRecord["wert"]?.text == "indigo")
        #expect(makeRecord.encrypted.isEmpty)
    }

    @Test("A round trip through JSON does not lose the secret list")
    func roundTrip() throws {
        let makeRecord = CloudRecord(
            type: "Senderliste", name: "xtream|a|b", fields: ["geheimnis": .text("kennwort")],
            encrypted: ["geheimnis"])
        let back = try JSONDecoder().decode(
            CloudRecord.self, from: JSONEncoder().encode(makeRecord))
        #expect(back == makeRecord)
        #expect(back.encrypted == ["geheimnis"])
    }
}
